Method.Source:
    public static str callstackAsHtml(container _stack, str _startAfter = '', boolean _hideZeroLineNumberLines = false)
    {
        str			html = '<table><tr><th><b>'+"@SYS1129" + '/' + "@SYS15097" + '</b></th><th><b>' + "@SYS15449" + '</b></th><th><b>' + "@SYS305181" + '</b></th><th><b>' + "@SYS9923" + '</b></th></tr>';
        int			i = 1;
        str			line;
        str			curLine;
        str			prevclsMethod;
        boolean		skipLine;
        container	stackCon = _stack;
        boolean		boldLine;
        boolean     startLineReached = _startAfter == '';

        while (conLen(stackCon))
        {
            curLine = strReplace(conPeek(stackCon,1),'`','');

			if (strScan(curLine,'\\',1,100))
            {
                if (prevclsMethod == curLine || strScan(curLine,'CoCHelper[class]',1,200))
                {
                    skipLine = true;
                }

                prevclsMethod = curLine;
                curLine = strReplace(strReplace(strReplace(curLine,'(','<i>('),')',')</i>'),'\\','.');
                boldLine = strScan(curLine,'[',1,100);

            }

            if (_startAfter != '' && !startLineReached)
            {
                skipLine = true;
            }
            if (_startAfter != '' && !startLineReached && strScan(curLine,_startAfter,1,200))
            {   
                startLineReached = true;
            }
            if (curLine == '0' && _hideZeroLineNumberLines)
            {
                skipLine = true;
            }
			if (boldLine)
            {
                curLine = '<b>' + curLine + '</b>';
            }
            line += '<td>' + curLine + '</td>';

			if (i div 4)
            {
                html += skipLine ? '' : ('<tr>' + line + '</tr>');
                line = '';
                i = 0;
                skipLine = false;
                boldLine = false;
            }
            stackCon = conDel(stackCon,1,1);
            i++;
        }

        return '<html><body>' + html + '</table></body></html>';
    }
